import sys

MOD = 10**9 + 7

def mat_mul(a, b):
    return [
        [(a[0][0]*b[0][0] + a[0][1]*b[1][0]) % MOD,
         (a[0][0]*b[0][1] + a[0][1]*b[1][1]) % MOD],
        [(a[1][0]*b[0][0] + a[1][1]*b[1][0]) % MOD,
         (a[1][0]*b[0][1] + a[1][1]*b[1][1]) % MOD]
    ]

def mat_pow(mat, power):
    res = [[1, 0], [0, 1]]
    while power:
        if power & 1:
            res = mat_mul(res, mat)
        mat = mat_mul(mat, mat)
        power >>= 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    k = int(data[0])
    w = int(data[1])

    if k == 1:
        if w == 1:
            print(-1)
        else:
            print(0)
        return

    if w == 1:
        print(-1)
        return

    # recurrence: a_n = (k-1)*a_{n-1} + k*a_{n-2}
    # initial: a_0 = 1, a_1 = k
    if w == 0:
        print(1 % MOD)
        return
    if w == 1:
        print(k % MOD)
        return

    A = [[k - 1, k],
         [1,     0]]
    M = mat_pow(A, w)
    a_w = (M[0][0] * k + M[0][1] * 1) % MOD
    print(a_w)

if __name__ == "__main__":
    main()
